/* RORUBARU trophy shelf - LIVE (Nov 15 2026).
   Earned badges come from the family_badges RPC (server-side award rules on
   approved bills, stamps, staff check-ins and sign-ups). No sample data:
   a member sees only badges they really earned. Badges carry no points,
   discounts or freebies. The shelf is private; sharing is the guest's choice. */
window.RORU_BADGES = (function () {
  // Badge art embedded as small WebP data URIs so the shelf is one file.
const IMGS = {
    'bottle-explorer': "data:image/webp;base64,",
    'bring-a-friend': "data:image/webp;base64,",
    'first-bite': "data:image/webp;base64,",
    'four-seasons': "data:image/webp;base64,",
    'full-roll-call': "data:image/webp;base64,",
    'kama-club': "data:image/webp;base64,",
    'night-owl': "data:image/webp;base64,",
    'rain-check': "data:image/webp;base64,",
    'regular': "data:image/webp;base64,",
    'roru-day': "data:image/webp;base64,",
    'season-chaser': "data:image/webp;base64,",
    'ten-rolls': "data:image/webp;base64,"
  };
  const CSS = `
.shelf{font:inherit;color:var(--cream,#f6f3e7);padding-bottom:calc(28px + env(safe-area-inset-bottom))}
.shelf-sample{background:var(--cream,#f6f3e7);color:var(--ink,#16181f);font-size:11px;font-weight:800;letter-spacing:.04em;border-radius:12px;padding:9px 12px;margin-bottom:14px;line-height:1.45}
.shelf-hero{background:var(--orange,#F64501);border-radius:20px;padding:18px;display:flex;gap:14px;align-items:center;color:#fff;box-shadow:0 10px 24px rgba(246,69,1,.25)}
.shelf-hero img{width:104px;height:104px;object-fit:contain;flex:0 0 auto;filter:drop-shadow(0 4px 8px rgba(0,0,0,.3))}
.shelf-hero .sh-new{display:inline-block;background:#fff;color:var(--orange,#F64501);font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;padding:3px 10px;border-radius:99px}
.shelf-hero h3{margin:8px 0 4px;font-size:24px;font-weight:900;letter-spacing:.02em}
.shelf-hero p{margin:0;font-size:13px;opacity:.92;line-height:1.4}
.shelf-hero .sh-when{margin-top:10px;padding-top:10px;border-top:1px solid rgba(255,255,255,.35);font-size:12px;font-weight:700}
.shelf-count{display:flex;align-items:baseline;justify-content:space-between;margin:18px 2px 6px}
.shelf-count h3{margin:0;font-size:18px;font-weight:900;letter-spacing:.03em;text-transform:uppercase}
.shelf-count b{font-size:15px;color:var(--orange,#F64501)}
.shelf-bar{height:6px;border-radius:99px;background:var(--ink2,rgba(246,243,231,.08));overflow:hidden;margin-bottom:14px}
.shelf-bar i{display:block;height:100%;background:var(--orange,#F64501);border-radius:99px}
.shelf-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px 10px}
.shelf-cell{text-align:center}
.shelf-cell img{width:100%;max-width:96px;aspect-ratio:1;object-fit:contain}
.shelf-cell .shf-name{font-size:12px;font-weight:800;margin-top:4px;line-height:1.2}
.shelf-cell .shf-when{font-size:11px;color:var(--muted,#a8a49a);margin-top:1px}
.shelf-cell.locked img{filter:grayscale(1) brightness(1.15);opacity:.45}
.shelf-cell.locked .shf-name{color:var(--muted,#a8a49a)}
.shelf-lock{display:inline-block;font-size:10px;margin-left:3px}
.shelf-note{font-size:12px;color:var(--muted,#a8a49a);margin-top:14px;line-height:1.5}
.shelf-share{appearance:none;border:1px solid var(--line,rgba(246,243,231,.16));background:transparent;color:inherit;font:inherit;font-size:13px;font-weight:700;padding:9px 16px;border-radius:99px;cursor:pointer;margin-top:10px}
`;

  // The 8 approved badges (names + one-liners from Dominic's badge art).
  const BADGES = [
    { id: "ten-rolls",       name: "Ten Rolls",       rule: "Your 10th visit" },
    { id: "regular",         name: "Regular",         rule: "Visited 3 months in a row" },
    { id: "four-seasons",    name: "Four Seasons",    rule: "Came in every quarter of the year" },
    { id: "full-roll-call",  name: "Full Roll Call",  rule: "All 27 core dishes stamped" },
    { id: "bottle-explorer", name: "Bottle Explorer", rule: "Worked through the drinks list" },
    { id: "kama-club",       name: "Kama Club",       rule: "Had a kama (fish collar) dinner" },
    { id: "bring-a-friend",  name: "Bring a Friend",  rule: "A friend signed up with your link" },
    { id: "night-owl",       name: "Night Owl",       rule: "Placed the last order of the night" }
  ];
  const ZH = {
    "ten-rolls":       { name: "Ten Rolls",       rule: "第 10 次光顧" },
    "regular":         { name: "Regular",         rule: "連續 3 個月都來過" },
    "four-seasons":    { name: "Four Seasons",    rule: "今年每季都來過" },
    "full-roll-call":  { name: "Full Roll Call",  rule: "集齊 27 款核心菜式印花" },
    "bottle-explorer": { name: "Bottle Explorer", rule: "飲遍今季酒單" },
    "kama-club":       { name: "Kama Club",       rule: "吃過魚下巴晚餐" },
    "bring-a-friend":  { name: "Bring a Friend",  rule: "朋友用你的連結加入" },
    "night-owl":       { name: "Night Owl",       rule: "點了當晚最後一單" }
  };

  const data = { loaded: false, earned: {}, earnedList: [], progress: {}, token: null };

  function zh() { try { return window.RORU && RORU.lang && RORU.lang() === "zh"; } catch (e) { return document.documentElement.lang !== "en"; } }
  function esc(s) { return String(s == null ? "" : s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])); }
  function fmtAt(iso) {
    const d = new Date(iso);
    return d.toLocaleDateString(zh() ? "zh-HK" : "en-HK", { day: "numeric", month: "short", year: "numeric", timeZone: "Asia/Hong_Kong" });
  }
  function img(id) { return IMGS[id] || ""; }
  function isFresh(at) { return at && (Date.now() - new Date(at).getTime()) < 24 * 3600 * 1000; }
  function progressFor(id) {
    const p = data.progress || {};
    if (id === "ten-rolls") return Math.min(p.bills || 0, 10) + " / 10";
    if (id === "full-roll-call") return Math.min(p.stamps || 0, p.stamps_total || 27) + " / " + (p.stamps_total || 27);
    if (id === "bottle-explorer") return Math.min(p.bottles || 0, p.bottles_total || 0) + " / " + (p.bottles_total || 0);
    return "";
  }

  async function load() {
    let tk = null;
    try { tk = localStorage.getItem("roru_member_token"); } catch (e) {}
    if (!tk || !window.RORU || !RORU.rpc) { data.loaded = false; return; }
    if (data.loaded && data.token === tk) return;
    try {
      const r = await RORU.rpc("family_badges", { p_token: tk });
      data.token = tk;
      data.progress = (r && r.progress) || {};
      data.earnedList = (r && r.earned) || [];
      data.earned = {};
      data.earnedList.forEach(b => { data.earned[b.id] = b; });
      data.loaded = true;
    } catch (e) { data.loaded = false; }
  }

  function shelfHtml() {
    const z = zh();
    const got = data.earned;
    const fresh = data.earnedList.find(b => isFresh(b.at));
    const n = BADGES.filter(b => got[b.id]).length;
    let html = '<div class="shelf">';
    if (fresh) {
      const nm = z && ZH[fresh.id] ? ZH[fresh.id].name : fresh.name || (BADGES.find(b => b.id === fresh.id) || {}).name || fresh.id;
      const rl = z && ZH[fresh.id] ? ZH[fresh.id].rule : (BADGES.find(b => b.id === fresh.id) || {}).rule || "";
      html += '<div class="shelf-hero"><img src="' + img(fresh.id) + '" alt="' + esc(nm) + ' badge">'
        + '<div><span class="sh-new">' + (z ? "新徽章" : "New badge") + '</span><h3>' + esc(nm) + '</h3>'
        + '<p>' + esc(rl) + '</p>'
        + '<div class="sh-when">' + (z ? "於 " : "Earned ") + esc(fmtAt(fresh.at)) + '</div></div></div>';
    }
    html += '<div class="shelf-count"><h3>' + (z ? "珍藏架" : "Trophy shelf") + '</h3><b>' + n + ' / ' + BADGES.length + '</b></div>'
      + '<div class="shelf-bar"><i style="width:' + Math.round(100 * n / BADGES.length) + '%"></i></div>'
      + '<div class="shelf-grid">';
    BADGES.forEach(b => {
      const g = got[b.id];
      const nm = z && ZH[b.id] ? ZH[b.id].name : b.name;
      const rl = z && ZH[b.id] ? ZH[b.id].rule : b.rule;
      const sub = g ? (z ? "於 " : "Earned ") + esc(fmtAt(g.at)) : (progressFor(b.id) || esc(rl));
      html += '<div class="shelf-cell' + (g ? '' : ' locked') + '">'
        + '<img src="' + img(b.id) + '" alt="' + esc(nm) + ' badge' + (g ? '' : ' (locked)') + '" loading="lazy">'
        + '<div class="sc-name">' + esc(nm) + (g ? '' : '<span class="shelf-lock">🔒</span>') + '</div>'
        + '<div class="sc-when">' + sub + '</div>'
        + '</div>';
    });
    html += '</div>'
      + (n ? '<button type="button" class="shelf-share">' + (z ? "分享我的珍藏架" : "Share my shelf") + '</button>' : '')
      + '<div class="shelf-note">' + (z
        ? "珍藏架只有你自己看得見 - 分不分享由你決定。徽章是紀念品，不影響積分或獎賞。"
        : "Your shelf is private to you - sharing is always your choice. Badges are keepsakes; they never affect points or rewards.") + '</div>'
      + '</div>';
    return html;
  }

  function paint(root) {
    root.innerHTML = shelfHtml();
    const shareBtn = root.querySelector(".shelf-share");
    if (shareBtn) shareBtn.onclick = async () => {
      const n = BADGES.filter(b => data.earned[b.id]).length;
      const text = zh()
        ? "我在 RORUBARU 的珍藏架：" + n + " / " + BADGES.length + " 個徽章 🏆"
        : "My RORUBARU trophy shelf: " + n + " of " + BADGES.length + " badges 🏆";
      try { if (navigator.share) { await navigator.share({ title: "RORUBARU trophy shelf", text: text }); return; } } catch (e) { return; }
      try { await navigator.clipboard.writeText(text); if (window.RORU && RORU.toast) RORU.toast(zh() ? "已複製" : "Copied"); } catch (e2) {}
    };
  }

  function mountInto(sec) {
    if (!sec || !sec.firstChild) return;              // passport feature off / not rendered
    if (!data.loaded) return;
    if (!document.getElementById("shelf-css")) {
      const st = document.createElement("style");
      st.id = "shelf-css";
      st.textContent = CSS;
      document.head.appendChild(st);
    }
    let box = document.getElementById("shelfLive");
    if (box && box.parentNode === sec) return;
    if (box) box.remove();
    box = document.createElement("div");
    box.id = "shelfLive";
    sec.insertBefore(box, sec.firstChild);
    paint(box);
  }

  async function boot() {
    const sec = document.getElementById("ppSec");
    if (!sec) return;
    await load();
    mountInto(sec);
    if (!boot.obs) {
      boot.obs = new MutationObserver(() => {
        const s = document.getElementById("ppSec");
        if (!s) return;
        if (s.firstChild && s.firstChild.id !== "shelfLive" && data.loaded) mountInto(s);
        if (s.firstChild && !document.getElementById("shelfLive") && data.loaded) mountInto(s);
      });
      boot.obs.observe(sec, { childList: true });
    }
    document.addEventListener("roru:signin", async () => { data.loaded = false; data.token = null; await load(); mountInto(document.getElementById("ppSec")); });
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot);
  else boot();
  // late mount: the passport tab may first render after sign-in
  let tries = 0;
  const iv = setInterval(async () => {
    tries++;
    const sec = document.getElementById("ppSec");
    if (sec && sec.firstChild && !document.getElementById("shelfLive")) { await load(); mountInto(sec); }
    if (tries > 240) clearInterval(iv);
  }, 5000);

  return { reload: async () => { data.loaded = false; data.token = null; await load(); const b = document.getElementById("shelfLive"); if (b) paint(b); }, BADGES: BADGES };
})();
